var flowEl = document.querySelector("#flow");
var zafuStatus = document.querySelector("#zafu-status");
var keplrStatus = document.querySelector("#keplr-status");
var balanceList = document.querySelector("#balances");
var beginButton = document.querySelector("#begin");
var restartButton = document.querySelector("#restart");
var readButton = document.querySelector("#read");
var beginStatus = document.querySelector("#begin-status");
var plan = document.querySelector("#plan");
var slices = document.querySelector("#slices");
var sliceCount = document.querySelector("#slice-count");
var sliceInterval = document.querySelector("#slice-interval");
